import sys; sys.path.insert(0, 'code')
from statistical_hardening import *
# Run W1 for SciERC only first
results = {}
for ds_name in ['scierc_n8', 'scierc_n16', 'conll_n8']:
    ds_cfg = DATASETS[ds_name]
    slow = True
    seed_results = {}
    for seed, path in sorted(ds_cfg['seeds'].items()):
        import os
        if not os.path.exists(path): continue
        print(f'{ds_name} seed {seed}...', end=' ', flush=True)
        import time; t0=time.time()
        data = load_data(path)
        m = compute_seed_metrics(data, compute_slow_signals=slow)
        seed_results[seed] = m
        print(f'n={m[\"n_instances\"]}, greedy={m[\"greedy_f1\"]:.4f}, LP={m[\"lp_sel_f1\"]:.4f} (D={m[\"lp_delta_pp\"]:+.2f}pp) [{time.time()-t0:.1f}s]')
    seeds = sorted(seed_results.keys())
    agg = {'seeds': seeds, 'n_seeds': len(seeds)}
    metrics_to_agg = ['greedy_f1','oracle_f1','headroom_pp','lp_sel_f1','lp_delta_pp','sj_sel_f1','em_sel_f1','sj_delta_pp','em_delta_pp']
    for metric in metrics_to_agg:
        vals = [seed_results[s][metric] for s in seeds if metric in seed_results[s]]
        agg[metric] = {'mean':float(np.mean(vals)), 'std':float(np.std(vals,ddof=1)) if len(vals)>1 else 0.0, 'per_seed':{str(s):seed_results[s][metric] for s in seeds if metric in seed_results[s]}}
    agg['n_instances'] = {str(s): seed_results[s]['n_instances'] for s in seeds}
    results[ds_name] = agg
    print(f'  => greedy={agg[\"greedy_f1\"][\"mean\"]:.4f}+/-{agg[\"greedy_f1\"][\"std\"]:.4f}, LP={agg[\"lp_sel_f1\"][\"mean\"]:.4f}+/-{agg[\"lp_sel_f1\"][\"std\"]:.4f}')
import json
with open(f'{OUT_DIR}/w1_partial.json','w') as f: json.dump(results,f,indent=2)
print('Saved partial W1')
